-- Run within a dedicated empty Oracle schema.
CREATE TABLE Kategoriya (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nazvanie VARCHAR2(50) NOT NULL UNIQUE);
CREATE TABLE Klient (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, fio VARCHAR2(100) NOT NULL, telefon VARCHAR2(20) UNIQUE, bonus INT DEFAULT 0 CHECK(bonus>=0), email VARCHAR2(100) CHECK(email LIKE '%@%'));
CREATE TABLE Sotrudnik (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, fio VARCHAR2(100) NOT NULL, id_boss INT REFERENCES Sotrudnik(id));
CREATE TABLE Tovar (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nazvanie VARCHAR2(100) NOT NULL UNIQUE, cena DECIMAL(10,2) NOT NULL CHECK(cena>0), id_kategoriya INT REFERENCES Kategoriya(id));
CREATE TABLE Zakaz (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_klient INT NOT NULL REFERENCES Klient(id), id_sotrudnik INT REFERENCES Sotrudnik(id), data DATE DEFAULT SYSDATE NOT NULL, summa DECIMAL(10,2) NOT NULL CHECK(summa>=0));
CREATE TABLE Sostav_zakaza (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id_zakaz INT NOT NULL REFERENCES Zakaz(id),id_tovar INT NOT NULL REFERENCES Tovar(id),qty INT NOT NULL CHECK(qty>0),price DECIMAL(10,2) NOT NULL CHECK(price>0));
